# owner: platform
import unittest

from rosterkit.seating import seating_rows
from rosterkit.models import Student
from rosterkit.errors import ProjectError


def make_student(last, first, number):
    return Student(str(number), last, first, "A")


class SeatingTests(unittest.TestCase):
    def setUp(self):
        self.roster = [
            make_student("Halloway", "Juno", 1),
            make_student("Dunmere", "Piet", 2),
            make_student("Adler", "Rosa", 3)
        ]

    def test_sorted_by_last_name_in_rows(self):
        self.assertEqual(
            seating_rows(self.roster, 2),
            [
                "Row 1: Adler, Rosa | Dunmere, Piet",
                "Row 2: Halloway, Juno"
            ]
        )

    def test_single_row_when_seats_exceed_students(self):
        self.assertEqual(
            seating_rows(self.roster, 10),
            [
                "Row 1: Adler, Rosa | Dunmere, Piet"
                " | Halloway, Juno"
            ]
        )

    def test_sorting_ignores_case(self):
        mixed = [
            make_student("zeta", "Ann", 1),
            make_student("Alpha", "Bob", 2)
        ]
        self.assertEqual(
            seating_rows(mixed, 1),
            ["Row 1: Alpha, Bob", "Row 2: zeta, Ann"]
        )

    def test_input_list_is_not_changed(self):
        before = list(self.roster)
        seating_rows(self.roster, 2)
        self.assertEqual(self.roster, before)

    def test_zero_seats_raises(self):
        with self.assertRaises(ProjectError):
            seating_rows(self.roster, 0)

    def test_negative_seats_raises(self):
        with self.assertRaises(ProjectError):
            seating_rows(self.roster, -3)

    def test_no_students_raises(self):
        with self.assertRaises(ProjectError):
            seating_rows([], 3)
